"""Compare summary JSON files generated by straight/circle evaluations."""

import argparse
import json
from pathlib import Path


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("summaries", nargs="+", type=Path)
    args = parser.parse_args()
    for path in args.summaries:
        data = json.loads(path.read_text(encoding="utf-8"))
        print(
            f"{path}: controller={data.get('controller')} "
            f"rmse={data.get('position_rmse_m', data.get('circle_radius_rmse_m')):.6f} m "
            f"mean_time={data.get('mean_controller_time_ms'):.3f} ms"
        )


if __name__ == "__main__":
    main()
